// Use adds a list of mutation hooks to the hooks stack.
// A call to `Use(f, g, h)` equals to `raguser.Hooks(f(g(h())))`.
func (c *RagUserClient) Use(hooks ...Hook) {
	c.hooks.RagUser = append(c.hooks.RagUser, hooks...)
}

// Intercept adds a list of query interceptors to the interceptors stack.
// A call to `Intercept(f, g, h)` equals to `raguser.Intercept(f(g(h())))`.
func (c *RagUserClient) Intercept(interceptors ...Interceptor) {
	c.inters.RagUser = append(c.inters.RagUser, interceptors...)
}

// Create returns a builder for creating a RagUser entity.
func (c *RagUserClient) Create() *RagUserCreate {
	mutation := newRagUserMutation(c.config, OpCreate)
	return &RagUserCreate{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// CreateBulk returns a builder for creating a bulk of RagUser entities.
func (c *RagUserClient) CreateBulk(builders ...*RagUserCreate) *RagUserCreateBulk {
	return &RagUserCreateBulk{config: c.config, builders: builders}
}

// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *RagUserClient) MapCreateBulk(slice any, setFunc func(*RagUserCreate, int)) *RagUserCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &RagUserCreateBulk{err: fmt.Errorf("calling to RagUserClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*RagUserCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &RagUserCreateBulk{config: c.config, builders: builders}
}

